    if(!Number.isSafeInteger(body.monthly_cents)||body.monthly_cents<=0||body.monthly_cents>100000000)return failure('Choose a monthly amount above $0.','invalid_amount',400);
    const goal=body.goal&&typeof body.goal==='object'&&math.GOAL_KINDS.includes(body.goal.kind)&&realDay(body.goal.by)?{kind:body.goal.kind,by:body.goal.by}:null;
    const plan=math.buildPlan(strategyInputs(day),{method:body.method,monthly_cents:body.monthly_cents,goal});
    if(!plan.ok)return failure('This plan cannot be saved with these numbers.','plan_not_ok',400);
    const saved={id:'sample-strategy-plan',method:body.method,monthly_cents:body.monthly_cents,goal,as_of:day,debt_free_on:plan.debt_free?.on??null,cash_check:plan.cash?.status??null,saved_by_kind:null,saved_at:stamp(),steps:Array.isArray(plan.milestones)?plan.milestones.length:0,sample:true};
    moneyState().strategy=saved;persist();return {ok:true,saved:copy(saved),sample:true};
