  const ALERT_KINDS={payment_timing:'Pay before the statement closes',promo_end:'Promo rate ending',cash_reserve:'Cash cushion',new_credit:'New credit'};
  /* The real evaluateReserve() rule: six months of minimums against the cash of the same kind. */
  function reserveFor(kind,day){
    const debts=kind==='personal'?[...sampleCards(day).map(c=>({balance_cents:c.balance_cents,min_cents:c.min_due_cents})),...sampleLoans(day).map(l=>({balance_cents:l.balance_cents,min_cents:l.payment_cents}))]:[];
    const owing=debts.filter(d=>d.balance_cents>0),known=owing.reduce((s,d)=>s+d.min_cents,0),cash=kind==='personal'?cashOn(day):null;
    const base={kind,months:6,cash_cents:cash,cash_is_floor:false,cash_accounts:kind==='personal'?cashAccounts.length:0,minimums_cents:owing.length?known:null,minimums_is_floor:false,unknown_minimums:0,clarity_cents:null,need_cents:owing.length?6*known:null,short_cents:null};
    if(!owing.length)return {...base,state:'unknown',reason:'no_minimums'};
    if(cash===null)return {...base,state:'unknown',reason:'no_cash_accounts'};
    return cash<base.need_cents?{...base,state:'below',reason:'below_need',short_cents:base.need_cents-cash,open_alert_id:null}:{...base,state:'ok',reason:'covered',open_alert_id:null};
  }
