    const cards=sampleCards(day).map(c=>{const a=MONEY.accounts.find(x=>x.id===c.account_id),close=closeDayOf(a),next=nextOnDay(day,close);
      return {account_id:c.account_id,name:c.name,mask:c.mask,kind:c.kind,balance_cents:c.balance_cents,limit_cents:c.limit_cents,used_pct:c.used_pct,statement_close_day:close,close_day_source:Number.isInteger(m.closeDays[c.account_id])?'manual':'provider',
        pay_before:{next_close_on:next,days_to_close:dayGap(day,next),unknown_reason:null,text_on:dayAdd(next,-3),texted:false,texted_at:null},promo:null};});
