  /* ── The Alerts board and the client's own alerts and bills (unit AL2) ────
     DATA.alerts.boards: the board the real read (fileAlertsPayload, which builds it
     with buildAlertBoard) made from this sample on each pull day. The demo's
     businesses and what the client adds change here, so each business and each
     added item go on it the way buildAlertBoard puts them; the unit test checks the
     result against the real read. A close day typed in here does not move the
     board's own dates. The input check and each item's view are the real ones
     (realCustomAlerts: src/finance/file-alerts/custom.mjs, embedded). */
  const CUSTOM=realCustomAlerts,ALERTS=DATA.alerts,SMART_RANK=Object.fromEntries(ALERTS.smartKinds.map((k,i)=>[k,i]));
  function customRows(){const m=moneyState();if(!Array.isArray(m.custom))m.custom=[];return m.custom;}
  function customList(day){return customRows().filter(r=>!r.archived_at).map(r=>CUSTOM.customView(r,{today:day,sent:[]}));}
  const boardKey=(kind,id)=>kind==='personal'?'personal':kind==='business'?(id?'biz:'+id:'business'):'unknown';
  const boardByDate=field=>(a,b)=>{const x=a[field]||'9999-12-31',y=b[field]||'9999-12-31';if(x!==y)return x<y?-1:1;return String(a.name||'').localeCompare(String(b.name||''));};
  function alertBoard(day,custom){
    const base=copy(ALERTS.boards[day===MONEY.asOf.updated?'updated':'initial']);
    const containers=financeContainers().filter(c=>c.id),kindOf=new Map(containers.map(c=>[String(c.id),c.kind]));
    const named=v=>typeof v==='string'&&v.trim()?v.trim():null,scopes=new Map();
    const scope=key=>{
      if(scopes.has(key))return scopes.get(key);
      let s;
      if(key.startsWith('biz:')){const id=key.slice(4),c=containers.find(x=>String(x.id)===id)||null;s={key,kind:'business',name:(c&&named(c.name))||ALERTS.looseNames.business,entity_id:id};}
      else s={key,kind:key==='personal'?'personal':key==='business'?'business':'unknown',name:ALERTS.looseNames[key]||key,entity_id:null};
      Object.assign(s,{payments:[],bills:[],smart:[]});scopes.set(key,s);return s;
    };
    scope('personal');
    /* Each business the client has, in the order the entities read gives them (name, then id). */
    const businesses=containers.filter(c=>c.kind==='business').map(c=>({...c,id:String(c.id),name:named(c.name)||''})).sort((a,b)=>a.name<b.name?-1:a.name>b.name?1:a.id<b.id?-1:a.id>b.id?1:0);
    for(const c of businesses)scope('biz:'+c.id);
    for(const s of base.scopes){const t=scope(s.key);t.payments.push(...s.payments);t.smart.push(...s.smart);}
    for(const it of custom){
      const k=it.scope==='personal'?null:it.entity_id?kindOf.get(String(it.entity_id)):null;
      const target=scope(it.scope==='personal'?'personal':k?boardKey(k,String(it.entity_id)):'business');
      const ph={on:it.phone_alert&&ALERTS.phoneOn[it.kind==='bill'?'custom_bill':'custom_alert']===true,alert_on:it.phone?it.phone.alert_on:null,reason:it.phone?it.phone.reason:null,sent:it.phone?it.phone.sent:null};
      if(it.kind==='alert')target.payments.push({id:'custom:'+it.id,type:'alert',name:it.name,account_id:null,item_id:it.id,institution:null,logo:null,due_on:it.next_on,amount_cents:it.amount_cents,amount_is:it.amount_cents===null?null:'amount',cadence:it.cadence,close_on:null,needs_close_day:false,late:false,phone_alert:it.phone_alert!==false,phone:ph});
      else target.bills.push({id:'custom:'+it.id,source:'added',bill_id:null,item_id:it.id,name:it.name,amount_cents:it.amount_cents,cadence:it.cadence,next_on:it.next_on,next_unknown_reason:it.next_on?null:'no_next_date',phone_alert:it.phone_alert!==false,phone:ph});
    }
    /* The bills the detector found go in after the added ones, as buildAlertBoard puts them. */
    for(const s of base.scopes)scope(s.key).bills.push(...s.bills);
    const out=[...scopes.values()];
    for(const s of out){
      s.payments.sort(boardByDate('due_on'));s.bills.sort(boardByDate('next_on'));
      s.smart.sort((a,b)=>(SMART_RANK[a.kind]-SMART_RANK[b.kind])||boardByDate('on')(a,b));
      s.counts={payments:s.payments.length,bills:s.bills.length,smart:s.smart.length};
    }
    const rank=s=>s.key==='personal'?0:s.key.startsWith('biz:')?1:s.key==='business'?2:3;
    out.sort((a,b)=>rank(a)-rank(b)||String(a.name).localeCompare(String(b.name)));
    const first=out.find(s=>s.counts.payments+s.counts.bills+s.counts.smart>0);
    return {...base,default_scope:(first||out[0]).key,checks:{...base.checks,custom:Array.isArray(custom)},scopes:out};
  }
  /* add_custom, update_custom, set_custom_phone and remove_custom: the same checks,
     words and answers as api/money/alerts.mjs and src/finance/file-alerts/custom.mjs,
     saved in this demo's own state. A business must be one of this sample's own.
     Removing one sets archived_at; nothing is deleted. */
  const CUSTOM_ACTIONS=['add_custom','update_custom','set_custom_phone','remove_custom'];
  function customAction(body){
    const today=moneyToday(),rows=customRows(),bad=(field,message,status=400)=>{throw new CUSTOM.FileAlertInputError(field,message,status);};
    const live=id=>rows.find(r=>r.id===id&&!r.archived_at)||null;
    const checkEntity=id=>{if(id&&!state.plan.businessPlans.businesses.some(b=>String(b.id).toLowerCase()===id))bad('entity_id','no such business',404);};
    if(body.action==='add_custom'){
      const input=CUSTOM.readCustomInput(body,{today});
      checkEntity(input.entity_id);
      if(rows.filter(r=>!r.archived_at).length>=CUSTOM.ITEMS_MAX)bad('kind',`you can keep up to ${CUSTOM.ITEMS_MAX} alerts and bills; remove one first`);
      const at=stamp(),row={id:crypto.randomUUID(),...input,created_by:'client',updated_by:'client',archived_at:null,created_at:at,updated_at:at};
      rows.push(row);persist();return {ok:true,action:body.action,saved:CUSTOM.customView(row,{today}),sample:true};
    }
    if(!CUSTOM.isUuid(body.id))bad('id','id is required and must be a uuid');
    const id=String(body.id).trim().toLowerCase();
    if(body.action==='update_custom'){
      const row=live(id);if(!row)bad('id','no such alert or bill',404);
      const input=CUSTOM.readCustomInput(body,{today,kind:row.kind});
      checkEntity(input.entity_id);
      /* Every field is replaced but the kind, as updateCustomItem() does. */
      Object.assign(row,{name:input.name,amount_cents:input.amount_cents,cadence:input.cadence,day_of_month:input.day_of_month,start_on:input.start_on,scope:input.scope,entity_id:input.entity_id,phone_alert:input.phone_alert,updated_by:'client',updated_at:stamp()});
      persist();return {ok:true,action:body.action,saved:CUSTOM.customView(row,{today}),sample:true};
    }
    if(body.action==='set_custom_phone'){
      if(typeof body.enabled!=='boolean')bad('enabled','enabled must be true or false');
      const row=live(id);if(!row)bad('id','no such alert or bill',404);
      Object.assign(row,{phone_alert:body.enabled,updated_by:'client',updated_at:stamp()});
      persist();return {ok:true,action:body.action,saved:{id:row.id,phone_alert:row.phone_alert===true},sample:true};
    }
    const row=live(id);if(!row)bad('id','no such alert or bill',404);
    Object.assign(row,{archived_at:stamp(),updated_by:'client',updated_at:stamp()});
    persist();return {ok:true,action:body.action,saved:{id:row.id,removed:true},sample:true};
  }
  function alertsAction(body){
    const m=moneyState();
    if(CUSTOM_ACTIONS.includes(body.action))return customAction(body);
    if(body.action==='set_alert'){
      if(!Object.hasOwn(ALERT_KINDS,body.kind)||typeof body.enabled!=='boolean')return failure('Choose a known alert and turn it on or off.','invalid_alert',400);
      m.alerts[body.kind]=body.enabled;m.alertsSaved=true;persist();return {ok:true,saved:{kind:body.kind,enabled:body.enabled},sample:true};
    }
    if(body.action==='set_statement_close_day'){
      if(!cardAccounts.some(a=>a.id===body.account_id)||!Number.isInteger(body.day)||body.day<1||body.day>31)return failure('Choose a sample card and a day from 1 to 31.','invalid_close_day',400);
      m.closeDays[body.account_id]=body.day;m.alertsSaved=true;persist();return {ok:true,sample:true};
    }
    return failure('This sample alert action is not supported.','demo_action_unavailable',409);
  }
