  function lettersAction(body){
    const letters=state.letters;
    if(body.action==='approve_letter'||body.action==='check_address'){
      /* Unit CYCLE (saveLetterStep): approve this letter version, then check its
         mailing address. The address check waits for the approval; replays change nothing. */
      if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(body.documentId||'')))return failure('Choose one of your saved letters.','invalid_letter',400);
      const letter=letters.letters.find(l=>l.documentId===body.documentId);if(!letter?.approval)return failure('That letter is not on your file.','letter_unavailable',404);
      if(body.action==='check_address'&&!letter.approval.approvedAt)return failure('Approve the letter first.','approve_first',409);
      if(body.action==='approve_letter'&&!letter.approval.approvedAt)letter.approval={approvedAt:stamp(),addressCheckedAt:null};
      if(body.action==='check_address'&&!letter.approval.addressCheckedAt)letter.approval={...letter.approval,addressCheckedAt:stamp()};
      persist();return {ok:true,documentId:letter.documentId,step:body.action==='approve_letter'?'approve':'address',to:copy(letter.to),versionId:letter.versionId,approval:copy(letter.approval),sample:true};
    }
    if(body.action==='quote'){
      if(!Array.isArray(body.documentIds)||!body.documentIds.length||body.documentIds.some(id=>!letters.letters.some(l=>l.documentId===id&&l.eligibleForMailing)))return failure('Choose current sample letters.');
      const items=letters.letters.filter(l=>body.documentIds.includes(l.documentId));const quoteVersion='sample:'+JSON.stringify(items.map(item=>[item.documentId,item.currentVersionId||item.versionId]));
      if(state.mailQuote?.quoteVersion===quoteVersion)return copy(state.mailQuote);
      if(letters.orders.some(o=>!['quoted','mailed','cancelled'].includes(o.status)))return failure('Finish the current sample mailing request before changing its letters.');
      for(const order of letters.orders)if(order.status==='quoted')order.status='cancelled';
      const orderId=id('mail');const quote={ok:true,id:orderId,orderId,status:'quoted',paymentState:'none',quoteVersion,items:copy(items),totalCents:9700,currency:'USD',returnAddressSummary:copy(letters.returnAddress),paymentOptions:[{id:'sample-hosted',label:'Sample hosted checkout — no real charge',kind:'hosted_checkout'}],checkoutUrl:null,envelopes:[]};state.mailQuote=quote;letters.orders.push(copy(quote));persist();return copy(quote);
    }
    if(body.action==='confirm'){
      const q=state.mailQuote;if(!q||body.orderId!==q.orderId||body.quoteVersion!==q.quoteVersion||body.authorization!==true||body.paymentOptionId!=='sample-hosted')return failure('Review and accept the current sample mailing quote.');
      const order=letters.orders.find(o=>o.id===q.orderId);if(!order)return failure('The current sample quote could not be found.');if(order.status==='quoted'){order.status='payment_pending';order.paymentState='awaiting_payment';order.checkoutUrl=previewUrl('payment',q.orderId);}else if(!['payment_pending','mail_pending','mailed'].includes(order.status))return failure('This sample quote is no longer active.');state.plan.letterReadiness={state:'requested',usableLetterCount:letters.letters.length,mailingOrderCount:letters.orders.length};persist();return {ok:true,order:copy(order),sample:true};
    }
    if(body.action==='status'){const order=letters.orders.find(o=>o.id===body.orderId);if(!order)return failure('Choose the current sample mailing order.');return {ok:true,order:copy(order),sample:true};}
    return failure('This sample mailing action is not supported.');
  }
