      if(p.startsWith('/api/money/')){const response=moneyRead(p,url);if(response)return response;}
      if(p==='/api/read/affiliate-portal')return {ok:true,enrolled:false,affiliate:null,rates:{direct:null,downline:null},referrals:[],payouts:[],gates:null,payoutBank:null,sample:true};
      if(p==='/api/org-brand')return {ok:true,brand:null,sample:true};
      if(p==='/api/content/welcome-video')return {ok:true,video:null,url:null,title:'Welcome to Fundhub',sample:true};
